-- 2026-09-30 の六曜バグ修正（旧暦テーブル方式）で判明した既知の不具合2件を「既知の不具合」に登録する（seed のみ。テーブル変更なし）。

INSERT INTO known_issues (title, severity, status, page, memo, created_at, updated_at) VALUES
    ('六曜：0時直前後の朔・中気（将来のΔT誤差で旧暦日付が1日ずれる可能性）', 'low', 'open', '/calendar',
     '旧暦テーブル（inc/lunar-table.php）は将来のΔT（地球自転の遅れ）を外挿式で計算しているため、朔・中気が0時（日本時間）に極端に近い日は実際の暦と1日ずれる可能性がある（外挿の誤差の大きさは不明。年が先になるほど大きくなる）。【六曜に影響しうる：将来の朔で0時から60秒以内】2051-11-03 23:59:09（0時の51秒前）、2074-08-22 23:59:07（53秒前）、2097-01-13 23:59:56（4秒前）。朔の日付が翌日にずれると、その旧暦月（約29〜30日間）の六曜が1つずつずれる。【参考：将来の朔で0時から5分以内】2035-01-10 +3分5秒、2044-11-19 -2分26秒、2050-02-22 +3分9秒、2051-08-07 +4分44秒、2052-10-23 +3分4秒、2071-04-01 +3分2秒、2092-02-08 +2分35秒。【六曜に影響しない（中気：1900〜2100年で0時から70秒以内の全件。0時の反対側へずらしても全月の月番号・閏が変わらないことを確認済み）】1917-09-24 00:00:14（+14秒）、1927-03-21 23:59:08（-52秒）、1950-01-20 23:59:42（-18秒）、2019-11-22 23:58:53（-67秒）、2030-02-18 23:59:40（-20秒）、2053-01-19 23:58:51（-69秒）、2095-12-22 00:00:27（+27秒）。【現在への影響】なし（最も近い該当は2051年）。【再確認のタイミング】ΔTの式を更新して表を再生成したとき、または国立天文台が該当年の暦要項を公開したとき（2051年分は2050年2月頃の見込み）。それまで対応不要。',
     strftime('%Y-%m-%dT%H:%M:%S+09:00', 'now', 'localtime'), strftime('%Y-%m-%dT%H:%M:%S+09:00', 'now', 'localtime')),
    ('開発用テスト run-all.php：失敗時の詳細表示に前のテストの出力が混ざる', 'low', 'open', NULL,
     'tests/run-all.php で exec($cmd, $output, $exitCode) の前に $output を空にしていないため、FAIL時の詳細表示に、それ以前に実行したスクリプトの出力が累積して表示される。PASS/FAIL判定は exit code で行っているため判定自体は正しい。修正案：ループ内で exec の前に $output = []; を追加。2026-09-30 六曜修正のレビューで発見、後続タスク。サイト利用者への影響なし（tests/ は非公開）。',
     strftime('%Y-%m-%dT%H:%M:%S+09:00', 'now', 'localtime'), strftime('%Y-%m-%dT%H:%M:%S+09:00', 'now', 'localtime'));
